-- mod-guild-adventure: stat weights per class, talent tree, variant and phase (generated by
-- tools/gen_stat_weights.py from the wowbot335 stat priority profiles, profiles/statprio; do not edit by hand).
-- variant 0 the tree, 1 its tank (Blood, Feral); phase 0 leveling, 1 preraid, 2 raid; stat: StatsType of
-- mod-playerbots without STATS_TYPE_.
DROP TABLE IF EXISTS `ga_stat_weight`;
CREATE TABLE `ga_stat_weight` (
  `class` TINYINT UNSIGNED NOT NULL,
  `tab` TINYINT UNSIGNED NOT NULL,
  `variant` TINYINT UNSIGNED NOT NULL,
  `phase` TINYINT UNSIGNED NOT NULL,
  `stat` VARCHAR(32) NOT NULL,
  `weight` FLOAT NOT NULL,
  `profile` VARCHAR(64) NOT NULL,
  PRIMARY KEY (`class`, `tab`, `variant`, `phase`, `stat`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='mod-guild-adventure: stat weights from the wowbot335 profiles';

